# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------

def build_app(nodes: List[str], port: int, refresh: float) -> DashboardGateway:
    gw = DashboardGateway(nodes=nodes, port=port, refresh_interval=refresh)
    gw.app.on_startup.append(gw.on_startup)
    gw.app.on_cleanup.append(gw.on_cleanup)
    return gw


def main():
    parser = argparse.ArgumentParser(
        description="A2A Mesh Dashboard Gateway — egy porton az összes node"
    )
    parser.add_argument(
        "--port", type=int, default=DEFAULT_DISCOVERY_PORT,
        help=f"Gateway port (default: {DEFAULT_DISCOVERY_PORT})"
    )
    parser.add_argument(
        "--nodes", type=str, default=None,
        help="Comma-separated node URL-ek (pl. http://localhost:8650,http://localhost:8651)"
    )
    parser.add_argument(
        "--nodes-file", type=str, default=DEFAULT_NODES_FILE,
        help=f"JSON fájl a node listával (default: {DEFAULT_NODES_FILE})"
    )
    parser.add_argument(
        "--refresh", type=float, default=5.0,
        help="Auto-frissítési intervallum másodpercben (default: 5.0)"
    )
    parser.add_argument(
        "--scan", action="store_true",
        help="Local port scan (8650-8660) ha nincs más forrás"
    )
    args = parser.parse_args()

    nodes = discover_nodes(explicit=args.nodes, nodes_file=args.nodes_file)

    if not nodes and args.scan:
        nodes = _scan_local_ports()

    if not nodes:
        print("[gateway] Nincs felfedezett node. Használd: --nodes http://localhost:8650", file=sys.stderr)
        print("[gateway] Indítás üres node listával (később hozzáadható)...", file=sys.stderr)

    print(f"[gateway] Node-ok ({len(nodes)}):")
    for n in nodes:
        print(f"  → {n}")
    print(f"[gateway] Gateway port: {args.port}")
    print(f"[gateway] Auto-frissítés: {args.refresh}s")
    print(f"[gateway] Dashboard: http://localhost:{args.port}")

    gw = build_app(nodes, args.port, args.refresh)
    web.run_app(gw.app, host="0.0.0.0", port=args.port, print=None)


if __name__ == "__main__":
    main()